            getReport().message(MessageId.CSS_020, getCorrectedEPUBLocation(path, declaration.getLocation().getLine(),
              declaration.getLocation().getColumn(), declaration.toCssString()), construct.toCssString());
            break;
        }
      }
      break;
    }
    default:
      break;
  }
}
